function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Ship
  ctx.fillStyle = '#0af';
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
  // Meteors
  ctx.fillStyle = '#a33';
  meteors.forEach((m) => {
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // UI
  ctx.fillStyle = '#000';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Hits: ${hits}/${maxHits}`, 10, 40);
  if (hits >= maxHits) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

input.newString:
function draw() {
  // Clear with dark space background
  ctx.fillStyle = '#000020';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // Draw starfield
  ctx.fillStyle = '#fff';
  stars.forEach(st => {
    ctx.beginPath();
    ctx.arc(st.x, st.y, st.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // Ship (already drawn as triangle)
  // Meteors with radial gradient for a glowing effect
  meteors.forEach((m) => {
    const grad = ctx.createRadialGradient(m.x, m.y, 0, m.x, m.y, m.r);
    grad.addColorStop(0, 'rgba(255,100,100,0.9)');
    grad.addColorStop(1, 'rgba(150,0,0,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // UI
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Hits: ${hits}/${maxHits}`, 10, 40);
  if (hits >= maxHits) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

